"use client"

import * as React from "react"

import { cn } from "@/registry/default/lib/utils"
import {
  MIDNIGHT,
  formatTimeOfDay,
  parseTimeOfDay,
  segmentLabel,
  segmentRange,
  segmentText,
  stepSegment,
  writeSegment,
  readSegment,
  type HourCycle,
  type TimeOfDay,
  type TimeSegment,
} from "@/registry/default/lib/time-segments"
import { useControllableState } from "@/registry/default/hooks/use-controllable-state"

const TYPEAHEAD_RESET_MS = 1000

type TypedDigits = { segment: TimeSegment; digits: string; typedAtMs: number }

function TimeField({
  value,
  defaultValue = "",
  onValueChange,
  hourCycle = 24,
  minuteStep = 1,
  name,
  disabled,
  className,
  ...props
}: Omit<React.ComponentProps<"div">, "defaultValue" | "onChange"> & {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  hourCycle?: HourCycle
  minuteStep?: number
  name?: string
  disabled?: boolean
}) {
  const { value: timeValue, setValue: setTimeValue } = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  })
  const segmentRefs = React.useRef<(HTMLSpanElement | null)[]>([])
  const typedDigitsRef = React.useRef<TypedDigits | null>(null)
  const time = parseTimeOfDay(timeValue)
  const segments: TimeSegment[] =
    hourCycle === 12 ? ["hour", "minute", "period"] : ["hour", "minute"]

  function commit(next: TimeOfDay) {
    setTimeValue(formatTimeOfDay(next))
  }

  function focusSegment(index: number) {
    segmentRefs.current[index]?.focus()
  }

  function typeDigit(
    segment: TimeSegment,
    index: number,
    digit: string,
    typedAtMs: number
  ) {
    const { min, max } = segmentRange(segment, hourCycle)
    const previous = typedDigitsRef.current
    const isContinuing =
      previous?.segment === segment &&
      typedAtMs - previous.typedAtMs < TYPEAHEAD_RESET_MS
    const combined = isContinuing ? previous.digits + digit : digit
    const digits = Number(combined) > max ? digit : combined
    const typedValue = Number(digits)
    const isComplete = digits.length === 2 || typedValue * 10 > max

    typedDigitsRef.current = isComplete ? null : { segment, digits, typedAtMs }
    if (typedValue >= min)
      commit(writeSegment(time ?? MIDNIGHT, segment, typedValue, hourCycle))
    if (isComplete) focusSegment(index + 1)
  }

  function typePeriod(key: string) {
    const periodIndex = { a: 0, p: 1 }[key.toLowerCase()]
    if (periodIndex === undefined) return
    commit(writeSegment(time ?? MIDNIGHT, "period", periodIndex, hourCycle))
  }

  function handleKeyDown(
    segment: TimeSegment,
    index: number,
    event: React.KeyboardEvent<HTMLSpanElement>
  ) {
    const current = time ?? MIDNIGHT
    const step = segment === "minute" ? minuteStep : 1
    const { min, max } = segmentRange(segment, hourCycle)

    switch (event.key) {
      case "ArrowUp":
      case "ArrowDown":
        event.preventDefault()
        commit(
          stepSegment(
            current,
            segment,
            event.key === "ArrowUp" ? step : -step,
            hourCycle
          )
        )
        return
      case "Home":
      case "End":
        event.preventDefault()
        commit(
          writeSegment(
            current,
            segment,
            event.key === "Home" ? min : max,
            hourCycle
          )
        )
        return
      case "ArrowLeft":
      case "ArrowRight":
        event.preventDefault()
        focusSegment(event.key === "ArrowLeft" ? index - 1 : index + 1)
        return
      case "Backspace":
      case "Delete":
        event.preventDefault()
        setTimeValue("")
        return
    }

    if (segment === "period") return typePeriod(event.key)
    if (/^\d$/.test(event.key)) {
      event.preventDefault()
      typeDigit(segment, index, event.key, event.timeStamp)
    }
  }

  return (
    <div
      role="group"
      data-slot="time-field"
      data-disabled={disabled || undefined}
      className={cn(
        "inline-flex h-9 w-fit items-center rounded-md border border-input bg-transparent px-2 font-mono text-sm tabular-nums shadow-xs transition-[color,box-shadow] dark:bg-input/30",
        "focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50",
        "data-disabled:pointer-events-none data-disabled:opacity-50",
        className
      )}
      {...props}
    >
      {segments.map((segment, index) => {
        const { min, max } = segmentRange(segment, hourCycle)
        const text = segmentText(time, segment, hourCycle)

        return (
          <React.Fragment key={segment}>
            {segment === "minute" && (
              <span aria-hidden className="text-muted-foreground">
                :
              </span>
            )}
            <span
              ref={(node) => {
                segmentRefs.current[index] = node
              }}
              role="spinbutton"
              tabIndex={disabled ? -1 : 0}
              data-slot="time-field-segment"
              data-placeholder={time ? undefined : ""}
              aria-label={segmentLabel(segment)}
              aria-valuemin={min}
              aria-valuemax={max}
              aria-valuenow={
                time ? readSegment(time, segment, hourCycle) : undefined
              }
              aria-valuetext={time ? text : "Empty"}
              onKeyDown={(event) => handleKeyDown(segment, index, event)}
              onBlur={() => {
                typedDigitsRef.current = null
              }}
              className={cn(
                "rounded-sm px-0.5 outline-none select-none focus:bg-accent focus:text-accent-foreground data-placeholder:text-muted-foreground",
                segment === "period" && "ml-1"
              )}
            >
              {text}
            </span>
          </React.Fragment>
        )
      })}
      {name && <input type="hidden" name={name} value={timeValue} />}
    </div>
  )
}

export { TimeField }

export type TimeSegment = "hour" | "minute" | "period"
export type HourCycle = 12 | 24
export type TimeOfDay = { hours: number; minutes: number }

export const MIDNIGHT: TimeOfDay = { hours: 0, minutes: 0 }

const SEGMENT_LABEL: Record<TimeSegment, string> = {
  hour: "Hours",
  minute: "Minutes",
  period: "AM/PM",
}

function padTwo(value: number) {
  return String(value).padStart(2, "0")
}

export function segmentLabel(segment: TimeSegment) {
  return SEGMENT_LABEL[segment]
}

export function segmentRange(segment: TimeSegment, hourCycle: HourCycle) {
  switch (segment) {
    case "hour":
      return hourCycle === 12 ? { min: 1, max: 12 } : { min: 0, max: 23 }
    case "minute":
      return { min: 0, max: 59 }
    case "period":
      return { min: 0, max: 1 }
  }
}

export function parseTimeOfDay(value: string): TimeOfDay | null {
  const match = /^(\d{1,2}):(\d{2})$/.exec(value)
  if (!match) return null
  const hours = Number(match[1])
  const minutes = Number(match[2])
  if (hours > 23 || minutes > 59) return null
  return { hours, minutes }
}

export function formatTimeOfDay({ hours, minutes }: TimeOfDay) {
  return `${padTwo(hours)}:${padTwo(minutes)}`
}

export function readSegment(
  time: TimeOfDay,
  segment: TimeSegment,
  hourCycle: HourCycle
) {
  switch (segment) {
    case "hour":
      return hourCycle === 12 ? time.hours % 12 || 12 : time.hours
    case "minute":
      return time.minutes
    case "period":
      return time.hours >= 12 ? 1 : 0
  }
}

export function writeSegment(
  time: TimeOfDay,
  segment: TimeSegment,
  segmentValue: number,
  hourCycle: HourCycle
): TimeOfDay {
  const isAfternoon = time.hours >= 12
  switch (segment) {
    case "hour":
      if (hourCycle === 24) return { ...time, hours: segmentValue }
      return { ...time, hours: (segmentValue % 12) + (isAfternoon ? 12 : 0) }
    case "minute":
      return { ...time, minutes: segmentValue }
    case "period":
      return { ...time, hours: (time.hours % 12) + segmentValue * 12 }
  }
}

export function stepSegment(
  time: TimeOfDay,
  segment: TimeSegment,
  delta: number,
  hourCycle: HourCycle
) {
  const { min, max } = segmentRange(segment, hourCycle)
  const size = max - min + 1
  const current = readSegment(time, segment, hourCycle)
  const wrapped = min + ((((current - min + delta) % size) + size) % size)
  return writeSegment(time, segment, wrapped, hourCycle)
}

export function segmentText(
  time: TimeOfDay | null,
  segment: TimeSegment,
  hourCycle: HourCycle
) {
  if (segment === "period") {
    if (!time) return "--"
    return readSegment(time, segment, hourCycle) === 1 ? "PM" : "AM"
  }
  if (!time) return "--"
  return padTwo(readSegment(time, segment, hourCycle))
}
